const C30 = "`C3-0` (type `concept_abstrait`, examen individuel imposé) désigne une population, non un écart présumé.";
const NODIM = "**Dimensions** : aucune ; aucun axe d'A2-DIM ne décrit directement ce sens (doctrine du lot 16).";
const TAG0 = "**Tags** : aucun, ni sur l'ENTRY ni sur le sens ; aucun candidat hérité n'était à écarter, et rien n'établit une association caractéristique avec un lieu (critère des tags de lieu du lot 02).";
const REL0 = "**Relations** : aucune ; aucune décision n'en pose, et le balayage global des relations reste fermé.";
