const AUTRES = (s) => "**Les autres fonctions d'A7 et d'A9** : " + s;

// Les six noms en 毎 : même analyse, appuyée sur la fiche de chacun
const TYPE_MAI = "**Type (A2-ST).** `concept_abstrait` : une récurrence n'est ni une entité, ni une occurrence, ni une condition. Contre `quantite_valeur` : le sens ne donne aucune quantité ni grandeur, il dit qu'un moment revient. Contre `evenement` : ce qui se répète est dit par le verbe de la phrase, non par ce mot. Le type n'est donc pas ici une catégorie de secours.";
const CAT_MAI = "**Catégorie, niveau 3 (A2-L3).** `temps › frequence › frequent`. A2-L3 ne connaît que « Fréquent ; Occasionnel ; Rare » ; une récurrence sans exception ne relève ni du deuxième ni du troisième. Le rythme annuel ou mensuel ne fait pas de ce sens un sens rare : le niveau dit la régularité du retour, non sa cadence (§5, autres constats).";
const QUANT_MAI = (mot) => "**`quantificateur` (A9, §3.4), examiné et non posé.** `C7-c` relève « chaque » et « tous » : ce terme traduit le morphème 毎 à l'intérieur du mot, que la fiche décompose ; il n'est pas une quantification portée par " + mot + " sur un autre mot. A9 exige de quantifier « un référent désigné par un autre mot », en en donnant l'étendue : le sens désigne ici un repère temporel qui revient. Les tours 毎X の + nom sont portés à l'arbitrage (§5, point 3).";
const AUTRES_MAI = AUTRES("`connecteur`, `discours`, `politesse`, `comparatif` et `intensifieur` n'ont aucun appui : le mot ne relie aucun énoncé, ne gère pas l'échange, n'accomplit aucun acte social et ne modifie aucun degré.");

